	void RootInstance::onDescendentAdded(Instance* instance)
	{
		ModelInstance::onDescendentAdded(instance);
		ControllersUsed.setDirty();
	}

	void RootInstance::onDescendentRemoving(const boost::shared_ptr<Instance>& instance)
