	void LocalBackpack::clearLocalCharacter()
	{
		if (localCharacter)
		{
			Notifier<Instance, DescendantAdded>::disconnect(localCharacter, this);
			Notifier<Instance, DescendantRemoving>::disconnect(localCharacter, this);
