int Vector3Bridge::on_mul(lua_State* L)
{
    G3D::Vector3 a;
    if (getValue(L, 1, a))
    {
        G3D::Vector3 b;
        if (getValue(L, 2, b))
        {
            pushVector3(L, a*b);
            return 1;
        }
        else
        {
            float x = tonumberClamped(L, 2);
            pushVector3(L, a*x);
            return 1;
        }
    }
    else
    {
        a = getObject(L, 2);
        float x = tonumberClamped(L, 1);
        pushVector3(L, a*x);
        return 1;
    }
}

int Vector3Bridge::on_div(lua_State* L)
{
    G3D::Vector3 a;
    if (getValue(L, 1, a))
