int Vector3Bridge::newVector3(lua_State* L)
{
    float vector[3];
    int nargs = std::min(3, lua_gettop(L));

    for (int i = 0; i < nargs; i++)
        vector[i] = tonumberClamped(L, i+1);

    for (int i = nargs; i < 3; i++)
