static int lerp(lua_State* L)
{
    G3D::Vector3& a = Vector3Bridge::getObject(L, 1);
    G3D::Vector3& b = Vector3Bridge::getObject(L, 2);
    float c = tonumberClamped(L, 3);

    G3D::Vector3 result = (b-a)*c + a;

    Vector3Bridge::pushNewObject(L, result);
    return 1;
