	frames[count % 100] = frame;
	++count;
}

// 00678630 (CRobloxView 0045e00d / 0045e302 / 0045e590, RbxEntity 0067de7d / 0067e277 / 0067ee23)
FrameHistory::Frame* FrameHistory::get(int ago)
{
	int index = count - ago - 1;
	return &frames[index % 100];
}

// 00679990 (RbxEntity 0067de8c)
float FrameHistory::median(int n)
{
	if (n > 99 || count < n)
		return -1.0f;
	std::vector<float> values(n);
	values.clear();
	for (int i = 1; i <= n; ++i)
		values.push_back(frames[(count - i) % 100].time);
	std::sort(values.begin(), values.end());
	return values[n / 2];
}

// 006786c0
VisualEngine::VisualEngine()
	: sceneManager(0), camera(0), renderTarget(0), viewport(0), twoD(0), largeVertexBufferSetting(-1)
{
}

// 0067a130
VisualEngine::~VisualEngine()
{
	if (!sRoot)
		return;
	if (sceneManager)
		sRoot->destroySceneManager(sceneManager);
	if (renderTarget)
		sRoot->detachRenderTarget(renderTarget);
	delete twoD;

	StringVector textureKeep;
	StringVector materialKeep;
	StringVector meshKeep;
	releaseUnusedResources(MaterialManager::getSingleton(), "Material", materialKeep);
	releaseUnusedResources(TextureManager::getSingleton(), "Texture", textureKeep);
	releaseUnusedResources(MeshManager::getSingleton(), "Mesh", materialKeep);
	dumpResources(MaterialManager::getSingleton(), "matl");
	dumpResources(TextureManager::getSingleton(), "tex");
	dumpResources(MeshManager::getSingleton(), "mesh");

	boost::call_once(&initializeSubMeshNames, subMeshNamesOnce);
	SubMeshNames& names = *subMeshNames;
	LogManager::getSingleton().logMessage("RBX sms c=" + StringConverter::toString(names.size()));
	if (!names.empty())
	{
		String remaining;
		for (SubMeshNames::const_iterator it = names.begin(); it != names.end(); ++it)
			remaining += " " + it->second;
		LogManager::getSingleton().logMessage("RBX sms remaining: " + remaining);
	}

	MeshPtr mesh(MeshManager::getSingleton().getByName("rbxvb"));
	if (!mesh.isNull())
	{
		int total = mesh->getNumSubMeshes();
		int used = 0;
		for (int i = 0; i < total; ++i)
			if (mesh->getSubMesh(i)->indexData)
				++used;
		LogManager::getSingleton().logMessage("RBX sm c=" + StringConverter::toString(used));
	}
	if (RbxSceneNode::spheres)
		LogManager::getSingleton().logMessage("RBX sm2sph c=" + StringConverter::toString(RbxSceneNode::spheres->size()));
}

