			rightInput = -0.9f;
		}
		else if (chaseAngle > Math::pi() * 54.0/360.0)
		{
			leftInput = 0.0f;
			rightInput = 0.9f;
		}
		else if (chaseAngle < Math::pi() * -54.0/360.0)
		{
			leftInput = 0.9f;
			rightInput = 0.0f;
		}
		else
		{
			leftInput = 0.9f;
			rightInput = 0.9f;
		}

		buffer[Controller::LEFT_TRACK_INPUT] = leftInput;
		buffer[Controller::RIGHT_TRACK_INPUT] = rightInput;
		buffer[Controller::RIGHT_LEFT_INPUT] = chaseAngle * (1.0f/Math::pi());
