		void buildShadowBox(const G3D::Vector3& halfSize, std::vector<G3D::Vector3>& vertices, std::vector<unsigned short>& indices)
		{
			vertices.reserve(8);
			indices.reserve(36);
			vertices.push_back(G3D::Vector3(-halfSize.x, -halfSize.y, -halfSize.z));
			vertices.push_back(G3D::Vector3(-halfSize.x, -halfSize.y, halfSize.z));
			vertices.push_back(G3D::Vector3(-halfSize.x, halfSize.y, -halfSize.z));
			vertices.push_back(G3D::Vector3(-halfSize.x, halfSize.y, halfSize.z));
			vertices.push_back(G3D::Vector3(halfSize.x, -halfSize.y, -halfSize.z));
			vertices.push_back(G3D::Vector3(halfSize.x, -halfSize.y, halfSize.z));
			vertices.push_back(G3D::Vector3(halfSize.x, halfSize.y, -halfSize.z));
