		{
			const float inset;
			const float shoulderInset;
		public:
			DeformTop(float inset, float shoulderInset)
				: inset(inset),
				  shoulderInset(shoulderInset)
			{
			}
			void operator()(G3D::Vector3& vertex, G3D::Vector3&, G3D::Vector2& tex, const G3D::Vector3&, const G3D::Vector2int16&)
			{
				if (vertex.x > 0)
				{
